import re
from jinja2 import BaseLoader, select_autoescape
from jinja2.sandbox import SandboxedEnvironment

_IDENT_RE = re.compile(r"^[A-Za-z0-9_]{1,32}\Z")
_TEMPLATE_CHARS = re.compile(r"[{}%$<>|]")

_env = SandboxedEnvironment(
    loader=BaseLoader(),
    autoescape=select_autoescape(["html", "xml"]),
)


def compile_identifier():
    return _IDENT_RE


def strip_template_syntax(text):
    return _TEMPLATE_CHARS.sub("", text)[:200]


def render_page(source, **context):
    return _env.from_string(source).render(**context)


def render_user_template(raw_source):
    return _env.from_string(raw_source).render()

