def preview_entry():
    # 入口D: 主题取自请求头, 先做调用方白名单校验
    theme = request.headers.get("X-Theme", "default")
    if theme not in helper.ALLOWED_THEMES:
        theme = "default"
    return helper.render_card(theme)


