    app.run(host="127.0.0.1", port=8080, debug=False)

"""模板渲染辅助模块: 模板源码全部来自代码内常量."""
import re

from jinja2 import select_autoescape
from jinja2.sandbox import SandboxedEnvironment

# 白名单模板表: 键与值均为硬编码常量, 与外部输入无关
_CARD_TEMPLATES = {
    "default": "<h1>Member Card</h1><p>status: standard</p>",
    "vip": "<h1>Member Card</h1><p>status: vip</p>",
    "black": "<h1>Member Card</h1><p>status: black</p>",
}

ALLOWED_THEMES = frozenset(_CARD_TEMPLATES)

_env = SandboxedEnvironment(autoescape=select_autoescape(["html"]))

_WELCOME_TPL = "<p>Welcome, {{ username }}!</p>"

_GREET_RE = re.compile(r"[A-Za-z0-9 .,!?-]{0,64}")


def render_card(tpl_name):
    # 防御1: 仅作白名单键查找, 未命中回退默认常量模板, 输入永不成为模板源码
    src = _CARD_TEMPLATES.get(tpl_name, _CARD_TEMPLATES["default"])
    return _env.from_string(src).render()


def render_welcome(username):
    # 防御2: 输入仅作为上下文变量的值传入, Jinja2 视其为纯数据不解析
    return _env.from_string(_WELCOME_TPL).render(username=username)


def render_greeting(message):
    # 防御3: fullmatch 白名单剔除花括号等全部模板定界符后再拼接
    if not _GREET_RE.fullmatch(message):
        message = "guest"
    return _env.from_string("<p>Msg: " + message + "</p>").render()

using System;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;

namespace AuditApi.Controllers
{
    // 审计日志查询：代理转发前端指定的日志聚合节点查询
    [ApiController]
    [Route("api/audit")]
    public class AuditLogController : ControllerBase
    {
        private static readonly HttpClient _client = new HttpClient();

        [HttpGet("query")]
        public async Task<IActionResult> QueryAuditLog()
        {
            // 入口：直接读取查询串参数，未做来源校验
            string logNode = Request.Query["logNode"].ToString();
            string range = Request.Query["range"].ToString();

            // 拼接目标 URL：logNode 占据主机位，完全由客户端控制
            string targetUrl = logNode + "/audit/logs?range=" + Uri.EscapeDataString(range);

            // sink：向该地址发起服务端 HTTP 请求
            HttpResponseMessage resp = await _client.GetAsync(targetUrl);
            string body = await resp.Content.ReadAsStringAsync();

            // 原样回显响应，构成可读取内网内容的回显型 SSRF
            return Content(body, "application/json");
        }
    }
}

