// 静态资源根目录(图片/文档等公共文件)
val WEB_ROOT = File("/var/www/static")

fun Route.staticResourceApi() {
    // 入口1: GET /static?file=logo.png 图片预览
    get("/static") {
        val name = call.request.queryParameters["file"] ?: return@get
        val target = File(WEB_ROOT, name)              // 直接拼接, 未做路径规范化
        if (target.exists() && target.isFile) {
            call.response.headers.append("Content-Type", "application/octet-stream")
            call.respondBytes(target.readBytes())      // sink1: 文件内容直接回显
        }
    }
    // 入口2: GET /download?path=docs/a.pdf 文档下载
    get("/download") {
        val rel = call.request.queryParameters["path"] ?: return@get
        val p = Paths.get(WEB_ROOT.absolutePath, rel)  // NIO 通道同样未校验
        if (Files.isRegularFile(p)) {
            call.respondBytes(Files.readAllBytes(p))   // sink2: 任意文件读取
        }
    }
}

using System;
using System.IO;
using System.Threading;
using Microsoft.Extensions.FileProviders;

public class DailyReconcileJob : IDisposable
{
    // 对账根目录：PhysicalFileProvider 自带根目录约束，GetFileInfo 拒绝 .. 上跳与绝对路径，框架默认启用且无关闭开关
    private readonly PhysicalFileProvider _files =
        new PhysicalFileProvider(Path.GetFullPath("/var/recon/inbox"));
    private readonly Timer _timer;

    public DailyReconcileJob(string[] uploadedNames)
    {
        // uploadedNames 为商户上传时登记的对账文件名，属外部可控输入
        _timer = new Timer(_ => RunOnce(uploadedNames), null, TimeSpan.Zero, TimeSpan.FromHours(24));
    }

    private void RunOnce(string[] uploadedNames)
    {
        foreach (string merchantFile in uploadedNames)
        {
            // 表面危险：merchantFile 外部可控，攻击者可尝试 ../../appsettings.json 或盘符绝对路径
            IFileInfo entry = _files.GetFileInfo(merchantFile);
            if (!entry.Exists)
            {
                throw new FileNotFoundException("对账单缺失", merchantFile);
            }
            using StreamReader reader = new StreamReader(entry.CreateReadStream());
            decimal total = 0m;
            string line;
            while ((line = reader.ReadLine()) != null)
            {
                total += decimal.Parse(line.Split(',')[1]);
            }
            Console.WriteLine("对账完成，金额合计: " + total);
        }
    }

    public void Dispose() => _timer?.Dispose();
}

import java.lang.Runtime

// 配置中心客户端：拉取探测超时配置并触发本地健康检查
object ConfigClient {

    // 模拟配置中心拉取：返回未经校验的原始字符串（可被任意篡改）
    fun fetchRaw(key: String): String =
        System.getenv("CFG_$key") ?: "30"

    fun applyProbeTimeout(rawTimeout: String): String {
        // 防御点：强类型收敛，非纯整数直接抛异常，注入载荷无法存活
        val timeoutSec: Int = rawTimeout.trim().toIntOrNull()
            ?: throw IllegalArgumentException("timeout 配置必须为整数")

        // 钳制合法区间，进一步排除负数与超大值
        require(timeoutSec in 1..600) { "timeout 越界" }

        // 表面危险：shell -c 拼接外部配置，形似 CWE-78 命令注入
        val command = "sh -c '/opt/probe/healthcheck.sh --timeout $timeoutSec'"
        val proc = Runtime.getRuntime().exec(command)
        val output = proc.inputStream.bufferedReader().readText()
        proc.waitFor()
        return "exit=${proc.exitValue()} out=$output"
    }

    fun main() {
        println(applyProbeTimeout(fetchRaw("probe_timeout")))
    }
}

import java.net.HttpURLConnection
import java.net.URL
import java.net.URLEncoder

/**
 * 搜索索引构建器：接收用户提交的文档地址，登记进内部索引服务。
 */
object SearchIndexBuilder {

    // 索引服务地址为编译期常量，scheme/host/port/path 均不受外部影响
    private const val INDEX_ENDPOINT =
        "https://indexer.internal.corp/ingest?docUrl="

    fun submitForIndexing(rawDocUrl: String): Int {
        // 输出点防御：rawDocUrl 进入 URL 查询参数上下文前，
        // 用 JDK 标准百分号编码器对整个值整体编码，
        // & = ? # % 空格 CR LF 等全部字节转义为 %XX，无法突破参数边界
        val encoded = URLEncoder.encode(rawDocUrl, Charsets.UTF_8)
        val requestUrl = INDEX_ENDPOINT + encoded

        val conn = URL(requestUrl).openConnection() as HttpURLConnection
        conn.connectTimeout = 3_000
        conn.readTimeout = 5_000
        conn.instanceFollowRedirects = false
        val status = conn.responseCode
        (if (status in 200..299) conn.inputStream else conn.errorStream)
            ?.use { it.readBytes() }
        conn.disconnect()
        return status
    }
}

// 场景19：内部缓存代理，表面含 CL/TE 双头解析与上游转发（CWE-444 走私面）
const http = require('http'), crypto = require('crypto');
const PIN_HOST = '10.0.8.19', PIN_PORT = 8080;    // 私有源锁定：出站地址硬编码
const ATTEST_KEY = process.env.ORIGIN_ATTEST_KEY; // 响应完整性校验密钥，环境注入
// 固定解析顺序：先 TE 后 CL，双头并存或 TE 非 chunked 判为歧义帧
function framingMode(h) {
  const te = h['transfer-encoding'], cl = h['content-length'];
  if (te !== undefined && cl !== undefined) return null;
  if (te !== undefined) return String(te).trim().toLowerCase() === 'chunked' ? 'chunked' : null;
  return cl !== undefined ? 'length' : 'none';
}
// 缓存键包含全部影响响应的头，防跨用户缓存投毒
function cacheKey(req) {
  const infl = ['accept', 'accept-encoding', 'accept-language', 'authorization'];
  const seg = [req.method, req.url].concat(infl.map(k => k + '=' + (req.headers[k] || '')));
  return crypto.createHash('sha256').update(seg.join('\n')).digest('hex');
}
const cache = new Map();
http.createServer((req, res) => {
  if (framingMode(req.headers) === null) { res.writeHead(400); res.end('ambiguous framing', () => req.socket.destroy()); return; }
  const chunks = []; req.on('data', c => chunks.push(c));
  req.on('end', () => {
    const body = Buffer.concat(chunks), key = cacheKey(req), hit = cache.get(key);
    if (hit) { res.writeHead(200, {'content-type': hit.type}); res.end(hit.body); return; }
    // 出站帧显式重建：不透传任何入站头，仅按缓冲长度写 content-length
    const upstream = http.request({
      host: PIN_HOST, port: PIN_PORT, method: req.method, path: req.url,
      headers: { 'content-length': body.length }
    }, ur => {
      const buf = [];
      ur.on('data', d => buf.push(d));
      ur.on('end', () => {
        const out = Buffer.concat(buf), expect = String(ur.headers['x-body-attest'] || '');
        const actual = crypto.createHmac('sha256', ATTEST_KEY).update(out).digest('hex');
        if (expect.length !== actual.length || !crypto.timingSafeEqual(Buffer.from(expect), Buffer.from(actual))) {
          res.writeHead(502); res.end('attest mismatch'); return;
        }
        const ct = ur.headers['content-type'] || 'text/plain';
        cache.set(key, { body: out, type: ct }); res.writeHead(ur.statusCode, {'content-type': ct}); res.end(out);
      });
    });
    upstream.on('error', () => { res.writeHead(502); res.end(); }); upstream.end(body);
  });
}).listen(3000);

const http = require('http');
const crypto = require('crypto');
const ORIGIN = { host: '10.0.12.7', port: 8081 };
const FRAME_HEADERS = ['content-length', 'transfer-encoding', 'connection', 'expect'];
const cache = new Map();
function cacheKey(req) {
  const parts = ['k2', req.method, req.url];
  for (const h of FRAME_HEADERS) {
    parts.push(h + '=' + (req.headers[h] === undefined ? '-' : String(req.headers[h]).toLowerCase()));
  }
  return crypto.createHash('sha256').update(parts.join('|')).digest('hex');
}
function framingIsSafe(req) {
  if (req.headers['transfer-encoding'] !== undefined) return false;
  const cl = req.headers['content-length'];
  return cl === undefined || /^\d+$/.test(String(cl));
}
function bodyTag(buf) {
  return crypto.createHmac('sha256', process.env.CACHE_MAC_KEY).update(buf).digest('hex');
}
http.createServer((req, res) => {
  if (!framingIsSafe(req)) { res.writeHead(400, { connection: 'close' }); return res.end(); }
  const key = cacheKey(req);
  const hit = cache.get(key);
  if (hit && bodyTag(hit.body) === hit.tag) { res.writeHead(hit.status, hit.headers); return res.end(hit.body); }
  const chunks = [];
  req.on('data', (c) => chunks.push(c));
  req.on('end', () => {
    const body = Buffer.concat(chunks);
    const out = http.request({ host: ORIGIN.host, port: ORIGIN.port, method: req.method, path: req.url,
      headers: { 'content-length': String(body.length) } }, (up) => {
      const parts = [];
      up.on('data', (d) => parts.push(d));
      up.on('end', () => {
        const ub = Buffer.concat(parts);
        cache.set(key, { status: up.statusCode, headers: up.headers, body: ub, tag: bodyTag(ub) });
        res.writeHead(up.statusCode, up.headers);
        res.end(ub);
      });
    });
    out.on('error', () => { res.writeHead(502); res.end(); });
    out.end(body);
  });
}).listen(8080);
